mapper.update:
update srm_return
   set status = 'SHIPPED', shipped_at = #{at}, ship_ref = #{trxRef}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where return_id = #{returnId} and status = 'CONFIRMED'

update srm_return
   set status = 'CONFIRMED', shipped_at = null, ship_ref = null, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where return_id = #{returnId} and status = 'SHIPPED' and ship_ref = #{trxRef}
